class Parent(metaclass=InheritDocstrings):
    @property
    def value(self):
        """Inherited property documentation."""
        return 1

class Child(Parent):
    @property
    def value(self):
        return 2

print(repr(Child.value.__doc__))
assert Child.value.__doc__ == Parent.value.__doc__

