import xarray as xr
import xarray.core.merge as m, sys
orig=m.merge_attrs
calls=[]
def wrapped(variable_attrs, combine_attrs, context=None):
    vals=list(variable_attrs)
    calls.append(([dict(v) for v in vals], type(context).__name__, repr(context)[:120]))
    return orig(vals, combine_attrs, context=context)
for mod in list(sys.modules.values()):
    if mod is not None and getattr(mod, 'merge_attrs', None) is orig:
        setattr(mod, 'merge_attrs', wrapped)
x=xr.DataArray([1,2], dims='time', coords={'time':[0,1]}, attrs={'kind':'variable'})
x.time.attrs={'standard_name':'time','long_name':'Time'}
r=xr.where(True,x,x,keep_attrs=True)
for i,c in enumerate(calls): print('CALL',i,c)
print('RESULT',r.time.attrs)

import xarray as xr
from xarray.core import duck_array_ops
from xarray.core.computation import apply_ufunc
x=xr.DataArray([1,2],dims='time',coords={'time':[0,1]},attrs={'kind':'variable'})
x.time.attrs={'standard_name':'time','long_name':'Time'}
policies={'drop':'drop','override':'override','idx0':lambda a,context:a[0], 'idx1':lambda a,context:a[1], 'context0':lambda a,context:a[0] if context else a[1]}
for name,p in policies.items():
 try:
  r=apply_ufunc(duck_array_ops.where,True,x,x,join='exact',dataset_join='exact',dask='allowed',keep_attrs=p)
  print(name,'VAR',r.attrs,'COORD',r.time.attrs)
 except Exception as e: print(name,'ERROR',type(e).__name__,str(e))
